  function mountMaps(){
    if(!current||!window.L)return;const all=items();if(!all.length)return;
    function draw(layer,item,i){const p=[item.lat,item.lng],geometry=item.parcelEvidence?.parcel?.complete?item.parcelEvidence.parcel.geometry:null;if(geometry)L.geoJSON(geometry,{interactive:false,style:{color:colors[i],weight:2,fillColor:colors[i],fillOpacity:.16}}).addTo(layer);L.marker(p,{interactive:false,keyboard:false,icon:L.divIcon({className:'compare-map-letter',html:`<span style="background:${colors[i]}">${String.fromCharCode(65+i)}</span>`,iconSize:[28,28],iconAnchor:[14,14]})}).addTo(layer);return p;}
    const make=(id,interactive,records)=>{
      const el=$(id);if(!el||!el.getClientRects().length)return;
      let record=maps.get(id);if(record&&record.element!==el){removeMap(record);maps.delete(id);record=null;}
      if(!record){const point=records[0].item,map=L.map(el,{center:[point.lat,point.lng],zoom:16,zoomAnimation:false,fadeAnimation:false,markerZoomAnimation:false,zoomControl:interactive,dragging:interactive,scrollWheelZoom:false,doubleClickZoom:interactive,boxZoom:interactive,keyboard:interactive,touchZoom:interactive,attributionControl:true});L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors',crossOrigin:true}).addTo(map);record={map,element:el,layer:L.layerGroup().addTo(map)};maps.set(id,record);}
      const target=interactive?config.target:null,position=JSON.stringify({sites:records.map(({item})=>key(item)),target:target?{lat:target.lat,lng:target.lng}:null}),signature=JSON.stringify({position,geometries:records.map(({item})=>item.parcelEvidence?.parcel?.complete?item.parcelEvidence.parcel.geometry:null)});
      if(record.signature!==signature){record.layer.clearLayers();const points=records.map(({item,i})=>draw(record.layer,item,i));if(target&&number(target.lat)&&number(target.lng)){L.circleMarker([target.lat,target.lng],{radius:8,color:'#fff',weight:3,fillColor:'#243c47',fillOpacity:1}).bindTooltip(safe(target.label),{permanent:true,direction:'top'}).addTo(record.layer);points.push([target.lat,target.lng]);}
        if(record.position!==position||!interactive){if(interactive)record.map.fitBounds(L.latLngBounds(points),{padding:[55,45],maxZoom:16,animate:false});else{const item=records[0].item,geometry=item.parcelEvidence?.parcel?.complete?item.parcelEvidence.parcel.geometry:null;if(geometry)record.map.fitBounds(L.geoJSON(geometry).getBounds(),{padding:[28,22],maxZoom:17,animate:false});else record.map.setView([item.lat,item.lng],16,{animate:false});}}
        record.signature=signature;record.position=position;
      }
      record.map.invalidateSize({pan:false,animate:false});
    };
    all.forEach((item,i)=>make('compare-mini-'+i,false,[{item,i}]));make('compare-shared-map',true,all.map((item,i)=>({item,i})));
  }
  async function runOperation(kind,all,work){
    if(busy.has(kind)||!all.length)return;busy.add(kind);operations[kind]={completed:0,total:all.length,failures:0};redraw();
    try{await Promise.allSettled(all.map(async item=>{try{if(await work(item)===false)operations[kind].failures++;}catch{operations[kind].failures++;}finally{operations[kind].completed++;redraw();}}));}
    finally{busy.delete(kind);redraw();}
  }
  async function loadClimate(){if(!window.PlanViewCompareClimate)return;await runOperation('climate',items(),async item=>{const data=await window.PlanViewCompareClimate.inspect(item);detailChange(item,'climate',data);return !Object.values(data||{}).some(record=>record?.reasonCode==='unavailable');});}
